ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 ImageFileName=/(rclone|winscp|filezilla|anydesk|rustdesk|cloudflared|logmein|ngrok)\.exe$/i
| case { ImageFileName=/(rclone|winscp|filezilla)\.exe$/i | exfil := 1 ; * | exfil := 0 }
| case { ImageFileName=/(anydesk|rustdesk|cloudflared|logmein|ngrok)\.exe$/i | ra := 1 ; * | ra := 0 }
| groupBy([aid, ComputerName], function=[sum(exfil, as=exfilCount), sum(ra, as=raCount), collect([ImageFileName, CommandLine])])
| exfilCount > 0
| raCount > 0
